// Package: Microsoft.Azure.Functions.Worker
// Package: Microsoft.Azure.Functions.Worker.Extensions.Http
// Package: Microsoft.Extensions.Http
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Azure.Functions.Worker;
using Microsoft.Extensions.Http;

var host = new HostBuilder()
    .ConfigureFunctionsWorkerDefaults()
    .ConfigureServices(services =>
    {
        // Singleton — shared across the host process
        services.AddSingleton<IWeatherCache, WeatherCache>();

        // Named or typed HttpClient via IHttpClientFactory
        services.AddHttpClient<IWeatherClient, WeatherClient>(client =>
        {
            client.BaseAddress = new Uri("https://api.weather.example.com");
            client.DefaultRequestHeaders.Add("Accept", "application/json");
            client.Timeout = TimeSpan.FromSeconds(10);
        });

        // Transient — new instance each time
        services.AddTransient<IReportGenerator, CsvReportGenerator>();

        // Configuration from appsettings.json
        services.Configure<WeatherOptions>(
            hostContext.Configuration.GetSection("Weather"));
    })
    .Build();

await host.RunAsync();

// appsettings.json:
// {
//   "Weather": {
//     "ApiKey": "your-api-key",
//     "CacheDurationMinutes": 10
//   }
// }

// Package: Microsoft.Azure.Functions.Worker
// Package: Microsoft.Azure.Functions.Worker.Extensions.Http
// Package: Microsoft.EntityFrameworkCore
using System.Data;
using Microsoft.Azure.Functions.Worker;
using Microsoft.Azure.Functions.Worker.Http;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace MyFunctionApp;

public class OrdersFunction
{
    private readonly ILogger<OrdersFunction> _logger;

    public OrdersFunction(ILogger<OrdersFunction> logger)
    {
        _logger = logger;
    }

    [Function("list-orders")]
    public async Task<HttpResponseData> ListOrdersAsync(
        [HttpTrigger(AuthorizationLevel.Function, "get", Route = "orders")]
        HttpRequestData req,
        FunctionContext context,
        CancellationToken cancellationToken)
    {
        // Create a scope for scoped services like DbContext
        var sp = context.InstanceServices.CreateScope().ServiceProvider;
        await using var db = sp.GetRequiredService<AppDbContext>();

        var orders = await db.Orders
            .AsNoTracking()
            .OrderByDescending(o => o.OrderDate)
            .Take(100)
            .ToListAsync(cancellationToken);

        var response = req.CreateResponse(System.Net.HttpStatusCode.OK);
        await response.WriteAsJsonAsync(orders, cancellationToken);
        return response;
    }
}

