// Package: Microsoft.Azure.Functions.Worker
// Package: Microsoft.Azure.Functions.Worker.Extensions.Http
// Package: Moq
// Package: FluentAssertions
using System.Net;
using Moq;
using Xunit;
using MyFunctionApp;

public class WeatherFunctionTests
{
    [Fact]
    public async Task GetWeatherAsync_ReturnsOk_WithCityData()
    {
        // Arrange
        var cache = new Mock<IWeatherCache>();
        cache.Setup(c => c.TryGet("London", out It.Ref<WeatherSummary?>.IsAny))
            .Returns(false);

        var weatherClient = new Mock<IWeatherClient>();
        weatherClient.Setup(c => c.GetCurrentAsync("London", It.IsAny<CancellationToken>()))
            .ReturnsAsync(new WeatherSummary("London", 14, "Cloudy"));

        var logger = Mock.Of<ILogger<WeatherFunction>>();
        var function = new WeatherFunction(cache.Object, logger, weatherClient.Object);

        var req = new DefaultHttpRequestData(new DefaultHttpRequest());

        // Act
        var response = await function.GetWeatherAsync(req, "London", CancellationToken.None);

        // Assert
        response.StatusCode.Should().Be(HttpStatusCode.OK);
    }
}

// Output: Test passes — function returns 200 OK with mocked weather data
